const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (value, digits = 0) => value == null || !Number.isFinite(Number(value)) ? 'Not calculated' : new Intl.NumberFormat('en-MY', {maximumFractionDigits: digits, minimumFractionDigits: digits}).format(Number(value));
const unit = (value, suffix, digits = 0) => value == null ? 'Not calculated' : `${num(value, digits)} ${suffix}`;
const money = value => value == null ? 'Not calculated' : `RM ${num(value, 2)}`;
const sourceName = asset => asset?.facility_id ? asset.name : asset?.source_asset_id?.replace(/^Hog_/, '').replaceAll('_', ' ') || 'Building';
const dateOnly = value => value ? new Date(`${value.slice(0,10)}T12:00:00Z`).toLocaleDateString('en-MY',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}) : '—';
const sourceHour = (utc, zone) => new Intl.DateTimeFormat('sv-SE', {timeZone:zone, year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(utc)).replace(' ','T');
const route = () => { const value = location.hash.replace('#','').split('?')[0].toLowerCase(); return PAGES.some(([id])=>id===value) ? value : 'overview'; };
async function q(path,options={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(`/api/workbench${path}`,{...options,signal:controller.signal,headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{})}});if(!response.ok){let message=`Request failed (${response.status})`;try{const payload=await response.json();message=typeof payload.detail==='string'?payload.detail:Array.isArray(payload.detail)?payload.detail.map(item=>item.msg).join('; '):message}catch{}throw Error(message)}return await response.json()}catch(error){if(error.name==='AbortError')throw Error('The local API took too long. Please retry.');throw error}finally{clearTimeout(timeout)}}
const post = (path, body) => q(path,{method:'POST',body:JSON.stringify(body)});
async function checkGeminiStatus(){try{const status=await q('/copilot/status');state.geminiStatus=status.available?'available':'unavailable'}catch{state.geminiStatus='unavailable'}if(state.chatOpen||state.page==='copilot')render()}
const stamp = () => `${dateOnly(state.data?.observed_window?.from)}–${dateOnly(state.data?.observed_window?.to)}`;
const actionButton = (id,label,cls='primary',extra='') => `<button type="button" class="${cls}" data-action="${id}" ${extra}>${label}</button>`;
function rememberView(){try{localStorage.setItem('energios-view',JSON.stringify({assetId:state.assetId,period:state.period}))}catch{}}
function selectAsset(id){state.calculating=false;simulatorUI.saved=null;simulatorUI.editing=null;simulatorUI.compare=[];state.assetId=id;state.spatialFacility=state.assets.find(a=>a.id===id)?.facility_id||null;state.preview=null;state.scenarioDraft=null;state.floor='whole';state.room='Overview';buildingView=null;installationView=null;state.chat=[];rememberView();return refresh();}
async function openFacility(id,view=null,focusAlert=false){const asset=state.assets.find(a=>a.facility_id===id);if(asset){townshipView=view;await selectAsset(asset.id);window.scrollTo({top:0,behavior:'instant'});if(focusAlert&&state.spatialFacility===id){const alert=facilityAlerts(id)[0];if(alert){selectFloor(alert.floor);selectFloorRoom(alert.id);document.querySelector('.floor-inspector')?.scrollIntoView({block:'nearest',behavior:'smooth'});}}}}
async function refresh(){
  if(!state.assetId)return;
  const sequence=++requestSequence;
  state.loading=true;state.error=null;render();
  try { const [data,township]=await Promise.all([q(`/state?asset_id=${encodeURIComponent(state.assetId)}&period=${state.period}`),q(`/township?period=${state.period}`)]);if(sequence!==requestSequence)return;state.data=data;state.township=township;syncAlertState(township.items);state.scenarioDraft={...data.config}; }
  catch(error){if(sequence!==requestSequence)return;state.error=error.message;state.data=null;}
  finally {if(sequence===requestSequence){state.loading=false;render();}}
}
async function init(){
  state.page=route();
  try { const result=await q('/assets');if(result.data_model_version!=='malaysia-v2')throw Error('Data update pending: restart the application server and reload to use the Malaysian dataset.');state.assets=[...(result.facilities||[]),...(result.items||[])];if(!state.assets.length)throw Error('No buildings are available.');const townshipAssets=state.assets.filter(asset=>asset.facility_id);state.assetId=townshipAssets.find(asset=>asset.id===storedPreferences.assetId)?.id||townshipAssets[0]?.id||state.assets[0].id;const actionAsset=new URLSearchParams(location.hash.split('?')[1]||'').get('asset');if(state.page==='action-simulator'&&townshipAssets.some(a=>a.id===actionAsset))state.assetId=actionAsset;state.spatialFacility=state.page==='overview'?null:state.assets.find(a=>a.id===state.assetId)?.facility_id||null;state.period=['day','week'].includes(storedPreferences.period)?storedPreferences.period:'day';await refresh();await checkGeminiStatus(); }
  catch(error){state.loading=false;state.error=error.message;render();}
}
function header(){
  return `<header class="topbar"><button class="mobile-menu" data-action="toggle-menu" aria-label="Navigation menu" aria-expanded="${state.menuOpen}">☰</button><a class="logo" href="#overview" aria-label="Nexora overview"><img class="logo-image" src="/assets/nexora-logo.png" alt="Nexora — Powering tomorrow, intelligently"></a>
  <nav class="nav ${state.menuOpen?'open':''}" aria-label="Main navigation">${PAGES.filter(([id])=>!['copilot','action-simulator'].includes(id)).map(([id,label])=>`<a href="#${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${({overview:'Overview',monitoring:'Real-Time & Forecast',carbon:'Carbon Dashboard'})[id]||label}</a>`).join('')}</nav>
  </header>`;
}
function filters(){const all=state.page==='overview'&&!state.spatialFacility;return `<div class="filters">${all?'<span class="badge gray">All 6 facilities</span>':`<div class="building-filter"><label class="select-wrap"><span class="sr-only">Township building</span><select id="building-select" aria-label="Choose a township building">${state.assets.filter(asset=>asset.facility_id).map(asset=>`<option value="${asset.id}" ${asset.id===state.assetId?'selected':''}>${esc(sourceName(asset))}</option>`).join('')}</select></label>${state.page==='monitoring'?'<small class="building-filter-hint">Choose one of the six township buildings to view its estimated profile.</small>':''}</div>`}<label class="select-wrap"><select id="period-select" aria-label="History window"><option value="day" ${state.period==='day'?'selected':''}>24-hour view</option><option value="week" ${state.period==='week'?'selected':''}>7-day view</option></select></label>${state.page==='monitoring'?'<button type="button" class="ghost monitoring-export" data-action="export-monitoring" aria-label="Export selected history and forecast as CSV">↓ <span>Export data</span></button>':''}</div>`}
function heading(title,subtitle,controls=true){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${controls?filters():''}</div>`}
function sourceStrip(){const d=state.data;return `<div class="source-strip"><span><i class="dot"></i><strong>${d.asset.facility_id?'Malaysia demo · CLEMD-derived':'Malaysia benchmark · CLEMD'}</strong> · ${stamp()} · ${esc(d.asset.timezone)}</span><span>${d.coverage?.missing_hours?`${d.coverage.available_hours}/${d.coverage.expected_hours} hours available · totals exclude gaps`:'Historical source · Calculated demo estimates'}</span></div>`}
function kpi(label,value,sub,kind='blue',icon='↗',series=null){const values=(series||state.data?.observed||[]).slice(-24).map(r=>r.consumption_kwh);const min=Math.min(...values),max=Math.max(...values),points=values.map((v,i)=>`${i*72/Math.max(values.length-1,1)},${26-(v-min)*20/Math.max(max-min,1)}`).join(' ');return `<div class="card kpi ${kind}"><span class="label">${label}</span><span class="kpi-icon">${icon}</span><div class="value">${value}</div><div class="sub">${sub}</div><svg class="sparkline" viewBox="0 0 74 30" aria-hidden="true"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></div>`}
function calendarHistory(data){
 if(!data.coverage?.missing_hours)return data.observed;
 const first=new Date(data.observed_window.from),rows=new Map(data.observed.map(r=>[Date.parse(r.timestamp),r]));
 return Array.from({length:data.coverage.expected_hours},(_,i)=>{const t=first.getTime()+i*3600000;return rows.get(t)||{timestamp:new Date(t).toISOString(),source_local_timestamp:sourceHour(new Date(t).toISOString(),data.asset.timezone),consumption_kwh:null};});
}
function chart(valuesA,valuesB,labels,{colors=['#e96b12','#f2a13a'],mode='split',height=205,labelsB=null,chartUnit='kWh',dashed=true,dashPattern='5 4',seriesATitle=null,seriesBTitle='Forecast',ariaLabel=null,xTickLabels=null}={}){
  const all=[...valuesA,...valuesB].filter(Number.isFinite),max=Math.max(...all,1)*1.15,min=0,w=700,h=height,left=34,right=12,top=12,bottom=29,innerW=w-left-right,innerH=h-top-bottom;
  const x=index=>left+index*innerW/Math.max(1,mode==='split'?valuesA.length+valuesB.length-1:Math.max(valuesA.length,valuesB.length)-1);
  const y=value=>top+(max-value)*innerH/max;
  const segment=(values,start=0)=>{const pts=values.map((v,i)=>[x(i+start),y(v)]);if(!pts.length)return '';let path=`M${pts[0].join(',')}`;for(let i=0;i<pts.length-1;i++){const p0=pts[Math.max(0,i-1)],p1=pts[i],p2=pts[i+1],p3=pts[Math.min(pts.length-1,i+2)];path+=` C${p1[0]+(p2[0]-p0[0])/6},${p1[1]+(p2[1]-p0[1])/6} ${p2[0]-(p3[0]-p1[0])/6},${p2[1]-(p3[1]-p1[1])/6} ${p2[0]},${p2[1]}`;}return path;};
  const line=(values,start=0)=>{const paths=[];let group=[],offset=start;values.forEach((v,i)=>{if(Number.isFinite(v)){if(!group.length)offset=start+i;group.push(v);}else if(group.length){paths.push(segment(group,offset));group=[];}});if(group.length)paths.push(segment(group,offset));return paths.join(' ');};
  const circle=(values,start,isForecast)=>values.map((v,i)=>Number.isFinite(v)?`<circle cx="${x(i+start).toFixed(1)}" cy="${y(v).toFixed(1)}" r="7" fill="transparent" stroke="transparent"><title>${esc(isForecast?seriesBTitle:(seriesATitle||(state.data?.asset.facility_id?'Estimated reference':'Recorded reference')))} · ${esc((isForecast&&labelsB?labelsB[i]:labels[i+start])||`Interval ${i+start+1}`)}: ${num(v,1)} ${esc(chartUnit)}</title></circle>`:'').join('');
  const bStart=mode==='split'?valuesA.length:0;
  const ticks=[0,.25,.5,.75,1].map(p=>`<line x1="${left}" x2="${w-right}" y1="${top+p*innerH}" y2="${top+p*innerH}"/><text class="chart-axis" x="2" y="${top+p*innerH+3}">${num(max*(1-p),0)}</text>`).join('');
  const xticks=xTickLabels?xTickLabels.map((label,i)=>`<text class="chart-axis" x="${x(i)}" y="${h-4}" text-anchor="middle">${esc(label)}</text>`).join(''):[0,.25,.5,.75,1].map(p=>`<text class="chart-axis" x="${left+p*innerW}" y="${h-4}" text-anchor="middle">${esc(labels[Math.round(p*(labels.length-1))]?.slice(11,16)||'')}</text>`).join('');
  return `<div class="chart-holder"><svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(ariaLabel||`Recorded and forecast ${chartUnit} chart; hover a point for its date and value`)}"><path d="${line(valuesA)} L${x(valuesA.length-1)},${top+innerH} L${left},${top+innerH}Z" fill="${colors[0]}" opacity="${valuesA.every(Number.isFinite)?'.055':'0'}"/><g class="chart-grid">${ticks}</g>${xticks}<path class="chart-line" stroke="${colors[0]}" d="${line(valuesA)}"/><path class="chart-line" stroke="${colors[1]}" ${dashed?`stroke-dasharray="${dashPattern}"`:''} d="${line(valuesB,bStart)}"/>${circle(valuesA,0,false)}${circle(valuesB,bStart,true)}</svg></div>`;
}
function forecastChart(metric='energy'){
  const d=state.data,factor=metric==='cost'?d.config.tariff_myr_per_kwh:metric==='carbon'?d.config.carbon_kg_per_kwh:1;
  if(factor==null)return '<div class="empty">The selected calculation factor is not configured.</div>';
  const colors=metric==='carbon'?['#ed6a0b','#f5a623']:metric==='cost'?['#c94e08','#f2a13a']:['#ed6a0b','#f5a623'];
  const chartUnit=metric==='cost'?'RM':metric==='carbon'?'kg CO₂e':'kWh';
  if(state.period==='week'){
    const daily=new Map(),predicted=new Map();
    for(const row of d.observed){const date=row.source_local_timestamp.slice(0,10);daily.set(date,(daily.get(date)||0)+row.consumption_kwh*factor);}
    for(const row of d.history_forecast||[]){const date=row.source_local_timestamp.slice(0,10);predicted.set(date,(predicted.get(date)||0)+row.forecast_kwh*factor);}
    const dates=[...new Set(calendarHistory(d).map(row=>row.source_local_timestamp.slice(0,10)))].sort();
    const matched=(d.history_forecast||[]).length===d.observed.length&&[...daily.keys()].every(date=>predicted.has(date));
    const dateLabel=date=>new Intl.DateTimeFormat('en-MY',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`));
    const metricLabel=metric==='cost'?'estimated cost':metric==='carbon'?'estimated carbon emissions':'energy';
    const ariaLabel=`Daily benchmark and historical forecast ${metricLabel} across ${dates.length} selected days for ${sourceName(d.asset)}. Orange solid line is benchmark; green dotted line is forecast.`;
    return chart(dates.map(date=>daily.get(date)??null),matched?dates.map(date=>predicted.get(date)??null):[],dates,{mode:'overlay',colors:[colors[0],'#278449'],dashPattern:'1 5',chartUnit,seriesATitle:'Benchmark',seriesBTitle:'Forecast (historical backtest)',xTickLabels:dates.map(dateLabel),ariaLabel})+(matched?'':'<p class="note">Historical forecast comparison is unavailable for this selection.</p>');
  }
  const a=d.observed.slice(-24),b=d.forecast;
  return chart(a.map(r=>r.consumption_kwh*factor),b.map(r=>r.forecast_kwh*factor),a.map(r=>r.source_local_timestamp),{mode:'overlay',labelsB:b.map(r=>sourceHour(r.timestamp,d.asset.timezone)),colors,chartUnit});
}
function monitoringTimelineChart(metric='energy'){
  const d=state.data;
  const factor=metric==='cost'?d.config.tariff_myr_per_kwh:metric==='carbon'?d.config.carbon_kg_per_kwh:1;
  if(factor==null)return '<div class="empty">The selected calculation factor is not configured.</div>';
  const historical=calendarHistory(d);
  const future=d.forecast||[];
  if(!historical.length||!future.length)return '<div class="empty">History or forecast data is unavailable for this selection.</div>';
  const chartUnit=metric==='cost'?'RM':metric==='carbon'?'kg CO₂e':'kWh';
  const historyValues=historical.map(row=>row.consumption_kwh==null?null:row.consumption_kwh*factor);
  const forecastValues=future.map(row=>row.forecast_kwh*factor);
  const timestamps=[...historical.map(row=>row.source_local_timestamp),...future.map(row=>sourceHour(row.timestamp,d.asset.timezone))];
  const multiplier=Number(d.asset.demo_basis?.load_multiplier)||1;
  const modelMae=Number(d.model?.test_metrics?.model?.mae_kwh);
  const errorGuide=!d.asset.facility_id&&Number.isFinite(modelMae)?modelMae*factor:null;
  const upper=errorGuide==null?[]:forecastValues.map(value=>value+errorGuide);
  const lower=errorGuide==null?[]:forecastValues.map(value=>Math.max(0,value-errorGuide));
  const max=Math.max(1,...historyValues.filter(Number.isFinite),...upper,...forecastValues)*1.08;
  const w=700,h=260,left=44,right=12,top=18,bottom=32,innerW=w-left-right,innerH=h-top-bottom;
  const count=historyValues.length+forecastValues.length;
  const x=index=>left+index*innerW/Math.max(1,count-1);
  const y=value=>top+(max-value)*innerH/max;
  const smoothPath=points=>{
    if(!points.length)return '';
    let dPath=`M${points[0][0].toFixed(1)},${points[0][1].toFixed(1)}`;
    for(let i=0;i<points.length-1;i++){
      const p0=points[Math.max(0,i-1)],p1=points[i],p2=points[i+1],p3=points[Math.min(points.length-1,i+2)];
      dPath+=` C${(p1[0]+(p2[0]-p0[0])/6).toFixed(1)},${(p1[1]+(p2[1]-p0[1])/6).toFixed(1)} ${(p2[0]-(p3[0]-p1[0])/6).toFixed(1)},${(p2[1]-(p3[1]-p1[1])/6).toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
    }
    return dPath;
  };
  const path=points=>{const groups=[];let group=[];for(const p of points){if(p)group.push(p);else if(group.length){groups.push(group);group=[];}}if(group.length)groups.push(group);return groups.map(smoothPath).join(' ');};
  const historyPoints=historyValues.map((value,index)=>Number.isFinite(value)?[x(index),y(value)]:null);
  const forecastPoints=forecastValues.map((value,index)=>[x(historyValues.length+index),y(value)]);
  const bandPath=errorGuide==null?'':`${path(upper.map((value,index)=>[x(historyValues.length+index),y(value)]))} ${path(lower.map((value,index)=>[x(historyValues.length+index),y(value)]).reverse()).replace(/^M/,'L')} Z`;
  const boundary=(x(historyValues.length-.5));
  const grid=[0,.25,.5,.75,1].map(position=>`<line x1="${left}" x2="${w-right}" y1="${top+position*innerH}" y2="${top+position*innerH}"/><text class="chart-axis" x="2" y="${top+position*innerH+3}">${num(max*(1-position),metric==='energy'?0:1)}</text>`).join('');
  const tickIndices=state.period==='week'?[0,24,48,72,96,120,144,168,count-1]:[0,6,12,18,24,30,36,42,count-1];
  const uniqueTicks=[...new Set(tickIndices)].filter(index=>index>=0&&index<count);
  const dateLabel=value=>new Intl.DateTimeFormat('en-MY',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(`${value.slice(0,10)}T12:00:00Z`));
  const ticks=uniqueTicks.map((index,tickIndex)=>{
    const isDayStart=index===0||index===historyValues.length;
    const label=state.period==='week'?(index===count-1?'23:00':dateLabel(timestamps[index])):(isDayStart?dateLabel(timestamps[index]):timestamps[index].slice(11,16));
    const anchor=tickIndex===0?'start':tickIndex===uniqueTicks.length-1?'end':'middle';
    return `<text class="chart-axis" x="${x(index)}" y="${h-5}" text-anchor="${anchor}">${esc(label)}</text>`;
  }).join('');
  const points=(values,offset,title)=>values.map((value,index)=>Number.isFinite(value)?`<circle cx="${x(offset+index).toFixed(1)}" cy="${y(value).toFixed(1)}" r="7" fill="transparent" stroke="transparent"><title>${esc(title)} · ${esc(timestamps[offset+index])}: ${num(value,1)} ${esc(chartUnit)}</title></circle>`:'').join('');
  const sourceLabel=d.asset.facility_id?'Estimated history':'Benchmark readings';
  const forecastLabel=d.asset.facility_id?'Estimated forecast':'Forecast · next 24 hours';
  const accessible=`${sourceLabel} followed by the next 24-hour ${forecastLabel.toLowerCase()}, in ${chartUnit}, for ${sourceName(d.asset)}. Missing source readings remain gaps; facility uncertainty is not calibrated.`;
  return `<div class="chart-holder"><svg class="chart monitoring-timeline" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(accessible)}"><rect class="monitoring-forecast-window" x="${boundary.toFixed(1)}" y="${top}" width="${(w-right-boundary).toFixed(1)}" height="${innerH}"/><text class="monitoring-axis-unit" x="${left}" y="${top-5}">${esc(chartUnit)}</text><g class="chart-grid">${grid}</g>${ticks}${errorGuide==null?'':`<path class="monitoring-mae-band" d="${bandPath}"/>`}<path class="chart-line" stroke="#ed6a0b" d="${path(historyPoints)}"/><path class="chart-line monitoring-forecast-line" stroke="#278449" stroke-dasharray="2 6" d="${path(forecastPoints)}"/><line class="monitoring-forecast-divider" x1="${boundary.toFixed(1)}" x2="${boundary.toFixed(1)}" y1="${top}" y2="${top+innerH}"/><text class="monitoring-phase-label" x="${left+5}" y="${top+12}">${esc(sourceLabel)}</text><text class="monitoring-phase-label monitoring-future-label" x="${Math.min(boundary+7,w-right-100)}" y="${top+12}">Next 24 hours</text>${points(historyValues,0,sourceLabel)}${points(forecastValues,historyValues.length,forecastLabel)}</svg></div>`;
}
function exportMonitoringData(){
  const d=state.data,rows=[['Building','Period','Local date/time','Series','Energy (kWh)','Estimated cost (MYR)','Estimated carbon (kg CO2e)','Source coverage (available / expected hours)']];
  const factors={cost:d.config.tariff_myr_per_kwh,carbon:d.config.carbon_kg_per_kwh};
  const append=(stamp,series,kwh)=>rows.push([sourceName(d.asset),state.period==='week'?'7-day':'24-hour',stamp,series,kwh.toFixed(3),factors.cost==null?'':(kwh*factors.cost).toFixed(2),factors.carbon==null?'':(kwh*factors.carbon).toFixed(3),`${d.coverage.available_hours}/${d.coverage.expected_hours}`]);
  if(state.period==='week'){
    const observed=new Map(),forecast=new Map();
    for(const row of d.observed){const day=row.source_local_timestamp.slice(0,10);observed.set(day,(observed.get(day)||0)+row.consumption_kwh)}
    for(const row of d.history_forecast||[]){const day=row.source_local_timestamp.slice(0,10);forecast.set(day,(forecast.get(day)||0)+row.forecast_kwh)}
    for(const day of [...observed.keys()].sort()){append(day,'Benchmark',observed.get(day));if(forecast.has(day))append(day,'Forecast (historical backtest)',forecast.get(day))}
  }else{
    for(const row of d.observed.slice(-24))append(row.source_local_timestamp,'Benchmark',row.consumption_kwh);
    for(const row of d.forecast||[])append(sourceHour(row.timestamp,d.asset.timezone),'Forecast (next 24 hours)',row.forecast_kwh);
  }
  const csv=rows.map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');
  link.href=url;link.download=`nexora-${sourceName(d.asset).toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${state.period}-energy-forecast.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
const ENERGY_LAYERS=[['hvac','HVAC'],['grid','Grid'],['solar','Solar']];
function energyLayerInfo(){const id=state.energyLayer,d=state.data,share=(d.asset.demo_basis?.hvac_share_percent||0)/100,enabled=d.asset.facility_id==='solar'||d.actions.some(a=>a.id==='solar'&&a.status==='approved');const values={hvac:d.metrics.projected_energy_kwh*share,grid:d.metrics.projected_grid_kwh,solar:enabled?d.dispatch.items.reduce((sum,r)=>sum+r.solar_kwh,0):0};const labels={hvac:['HVAC allocation','Energy allocated'],grid:['Grid supply','Energy required'],solar:['Solar generation','Energy generated']};return `<strong>${labels[id][0]}</strong><span>${labels[id][1]}: <b>${unit(values[id],'kWh',1)}</b></span><small>Next 24 hours · approved planning scenario</small>`}

function selectFloor(floor){
  if(!floorOptions(state.spatialFacility).some(f=>f.id===floor))return;
  if(floor===state.floor)return;
  state.floor=floor;state.room='Overview';
  if(previewInstance?.setFloor){previewInstance.setFloor(floor);document.querySelectorAll('[data-floor]').forEach(button=>{const active=button.dataset.floor===floor;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});updateFloorInspector();}
  else {buildingView=previewInstance?.getView?.()||null;render();}
}
function updateFloorInspector(){const panel=document.querySelector('.floor-inspector');if(panel)panel.outerHTML=floorInspector();}
function selectFloorRoom(room){state.room=room;updateFloorInspector();}
function floorNavigator(){
  if(!state.spatialFacility||state.spatialFacility==='solar')return '';
  return `<nav class="floor-navigation" aria-label="Select building floor">${floorOptions(state.spatialFacility).map(f=>{const issues=floorIssueCount(state.spatialFacility,f.id);return `<button type="button" data-floor="${f.id}" aria-pressed="${state.floor===f.id}" class="${state.floor===f.id?'active':''}" title="${f.label}${issues?' · '+issues+' estimated alert':''}">${f.label}${issues?'<span class="floor-alert" aria-label="Floor alert">!</span>':''}</button>`}).join('')}</nav>`;
}
function floorInspector(){
  if(!state.spatialFacility)return '';
  if(state.spatialFacility==='solar')return '<div class="floor-inspector"><strong>Solar farm · Outdoor site</strong><p>No occupied floors in this model.</p></div>';
  const options=floorOptions(state.spatialFacility),zones=floorZones(state.spatialFacility,state.floor),label=options.find(f=>f.id===state.floor)?.label||'Whole building';
  if(!zones.length)return `<section class="floor-inspector">${floorSupply(state.township?.energy_network,state.spatialFacility,'whole')}<div class="floor-inspector-head"><h3>Explore inside</h3><span class="badge gray">Estimated conditions</span></div><p>${facilityAlerts(state.spatialFacility).length?'Select a floor above or click an alert below to inspect it.':'All floor alerts are settled. Select a floor to explore.'}</p><div class="building-alert-list">${facilityAlerts(state.spatialFacility).map(a=>`<button type="button" data-alert-floor="${a.floor}" data-alert-zone="${a.id}"><span class="alert-list-symbol" aria-hidden="true">!</span><span><strong>${esc(a.floorLabel)} · ${esc(a.name)}</strong><small>${esc(a.issue)}</small></span><b>View →</b></button>`).join('')}</div><small>${FLOOR_COUNTS[state.spatialFacility]} occupied floors · Roof plant · Estimated conditions</small></section>`;
  const selected=zones.find(z=>z.id===state.room)||zones.find(z=>z.status!=='Normal')||zones[0],days=1,hvac=state.data.metrics.projected_energy_kwh*(state.data.asset.demo_basis.hvac_share_percent/100)*state.data.asset.demo_basis.floor_hvac_weights[state.floor];
  return `<section class="floor-inspector" aria-label="Floor conditions"><div class="floor-inspector-head"><h3>${esc(label)} · Room conditions</h3><span class="badge gray">Estimated</span></div>${floorSupply(state.township?.energy_network,state.spatialFacility,state.floor)}<p>${state.floor==='roof'?'Roof equipment view':'Cutaway view'} · Select a zone to inspect.</p><div class="floor-zones">${zones.map(z=>`<button type="button" data-floor-zone="${z.id}" aria-pressed="${z.id===selected.id}" class="floor-zone ${z.status.toLowerCase()} ${z.id===selected.id?'selected':''}"><span class="zone-status-dot"></span><strong>${esc(z.name)}</strong><small>${z.status}${z.temperature==null?'':' · '+num(z.temperature,1)+'°C'}</small></button>`).join('')}</div><div class="floor-issue-detail ${selected.status.toLowerCase()}" role="status"><strong>${esc(selected.name)} · ${selected.status}</strong><p>${esc(selected.issue)}</p><p><strong>AI suggestion:</strong> ${esc(selected.action)}</p><div class="floor-condition-values"><span>Temperature <b>${selected.temperature==null?'Not applicable':num(selected.temperature,1)+'°C'}</b></span><span>Occupancy <b>${selected.occupancy} people</b></span><span>Allocated HVAC <b>${unit(hvac*selected.share,'kWh',1)}</b></span></div></div><details class="details"><summary>Calculation basis</summary><p>Next-24-hour room scenario. HVAC allocation = forecast building kWh × assumed HVAC share × floor allocation (${num(state.data.asset.demo_basis.floor_hvac_weights[state.floor]*100,1)}%) × zone share · ${days===7?'7 days':'24 hours'}. No sensor or equipment connection. Coloured zones are conceptual and are not an architectural floor plan.</p></details></section>`;
}
